#include "hybrid_core.h"
#define Q15_ONE 32767
/* Freestanding AC79 build: avoid requiring a hosted C library. */
static void hybrid_zero(void *ptr, uint32_t bytes){uint8_t *p=(uint8_t *)ptr;while(bytes--)*p++=0;}
static int32_t clamp_q15(int64_t x){if(x>32767)return 32767;if(x< -32768)return -32768;return (int32_t)x;}
/* Q15 fraction without 64-bit divide/multiply helpers (pi32v2 freestanding ABI). */
static uint16_t ratio_q15(uint32_t n,uint32_t d){uint16_t q=0;uint8_t i;if(!d||n>=d)return 32767;for(i=0;i<15;i++){q=(uint16_t)(q<<1);if(n>=d-n){n-=d-n;q|=1u;}else n<<=1;}return q;}
static uint8_t note_in_zone(const hybrid_channel_config_t*c,uint8_t n){if(!c->enabled||c->route_mode==HYBRID_ROUTE_OFF)return 0;if(c->route_mode==HYBRID_ROUTE_GLOBAL)return 1;return (uint8_t)(n>=c->key_low&&n<=c->key_high);}
static uint8_t any_solo(const hybrid_core_t*h){uint8_t i;for(i=0;i<HYBRID_CHANNELS;i++)if(h->engine[i].config.solo)return 1;return 0;}
void hybrid_init_defaults(hybrid_core_t*h){uint8_t i;if(!h)return;hybrid_zero(h,(uint32_t)sizeof(*h));for(i=0;i<HYBRID_CHANNELS;i++){hybrid_channel_config_t*c=&h->engine[i].config;c->enabled=1;c->route_mode=HYBRID_ROUTE_GLOBAL;c->key_high=127;c->velocity_low=1;c->velocity_high=127;c->volume=Q15_ONE;}h->selected_engine=HYBRID_AMB;}
int hybrid_register_engine(hybrid_core_t*h,hybrid_channel_id_t id,const hybrid_engine_ops_t*ops,void*state){if(!h||id>=HYBRID_CHANNELS||!ops||(!ops->render&&!ops->init))return -1;h->engine[id].ops=ops;h->engine[id].state=state;return 0;}
int hybrid_start(hybrid_core_t*h){uint8_t i;if(!h)return -1;for(i=0;i<HYBRID_CHANNELS;i++){hybrid_engine_slot_t*s=&h->engine[i];if(s->ops&&s->ops->init&&s->ops->init(s->state)!=0){hybrid_reset(h);return -1;}}h->initialized=1;return 0;}
void hybrid_reset(hybrid_core_t*h){uint8_t i;if(!h)return;for(i=0;i<HYBRID_CHANNELS;i++){hybrid_engine_slot_t*s=&h->engine[i];if(s->ops&&s->ops->reset)s->ops->reset(s->state);s->pcm_valid=0;s->pcm_frames=0;}h->initialized=0;h->transition_active=0;}
void hybrid_set_route(hybrid_core_t*h,hybrid_channel_id_t id,hybrid_route_mode_t m,uint8_t lo,uint8_t hi){hybrid_channel_config_t*c;if(!h||id>=HYBRID_CHANNELS||m>HYBRID_ROUTE_ZONE)return;if(lo>hi){uint8_t t=lo;lo=hi;hi=t;}c=&h->engine[id].config;c->route_mode=(uint8_t)m;c->key_low=lo;c->key_high=hi;}
void hybrid_set_volume(hybrid_core_t*h,hybrid_channel_id_t id,uint16_t v){if(h&&id<HYBRID_CHANNELS)h->engine[id].config.volume=v>Q15_ONE?Q15_ONE:v;}
void hybrid_set_pan(hybrid_core_t*h,hybrid_channel_id_t id,int16_t p){if(!h||id>=HYBRID_CHANNELS)return;if(p< -100)p=-100;if(p>100)p=100;h->engine[id].config.pan=p;}
void hybrid_set_mute(hybrid_core_t*h,hybrid_channel_id_t id,uint8_t m){if(h&&id<HYBRID_CHANNELS)h->engine[id].config.mute=!!m;}
void hybrid_set_solo(hybrid_core_t*h,hybrid_channel_id_t id,uint8_t s){if(h&&id<HYBRID_CHANNELS)h->engine[id].config.solo=!!s;}
void hybrid_note_on(hybrid_core_t*h,uint8_t n,uint8_t v,uint8_t ch){uint8_t i;if(!h||n>127||!v)return;for(i=0;i<HYBRID_CHANNELS;i++){hybrid_engine_slot_t*s=&h->engine[i];hybrid_channel_config_t*c=&s->config;int nn;if(!s->ops||!s->ops->note_on||!note_in_zone(c,n)||(c->midi_channel&&c->midi_channel!=ch)||v<c->velocity_low||v>c->velocity_high)continue;nn=(int)n+c->transpose;if(nn<0)nn=0;if(nn>127)nn=127;s->ops->note_on(s->state,(uint8_t)nn,v);}}
void hybrid_note_off(hybrid_core_t*h,uint8_t n,uint8_t ch){uint8_t i;if(!h||n>127)return;for(i=0;i<HYBRID_CHANNELS;i++){hybrid_engine_slot_t*s=&h->engine[i];hybrid_channel_config_t*c=&s->config;int nn;if(!s->ops||!s->ops->note_off||!note_in_zone(c,n)||(c->midi_channel&&c->midi_channel!=ch))continue;nn=(int)n+c->transpose;if(nn<0)nn=0;if(nn>127)nn=127;s->ops->note_off(s->state,(uint8_t)nn);}}
void hybrid_control(hybrid_core_t*h,uint16_t p,int32_t v,int8_t id){uint8_t i;if(!h)return;if(id>=0&&id<(int8_t)HYBRID_CHANNELS){hybrid_engine_slot_t*s=&h->engine[(uint8_t)id];if(s->ops&&s->ops->control)s->ops->control(s->state,p,v);return;}for(i=0;i<HYBRID_CHANNELS;i++){hybrid_engine_slot_t*s=&h->engine[i];if(s->ops&&s->ops->control)s->ops->control(s->state,p,v);}}
int hybrid_submit_pcm(hybrid_core_t*h,hybrid_channel_id_t id,const int32_t*pcm,uint16_t frames){hybrid_engine_slot_t*s;if(!h||id>=HYBRID_CHANNELS||!pcm||!frames||frames>HYBRID_MAX_FRAMES)return -1;s=&h->engine[id];if(s->pcm_valid)return -2;{uint16_t i;for(i=0;i<(uint16_t)(frames*2u);i++)s->pcm_input[i]=pcm[i];}s->pcm_frames=frames;s->pcm_valid=1;return 0;}
void hybrid_discard_pcm(hybrid_core_t*h,hybrid_channel_id_t id){if(h&&id<HYBRID_CHANNELS){h->engine[id].pcm_valid=0;h->engine[id].pcm_frames=0;}}
static void advance_transition(hybrid_core_t*h,uint16_t frames){uint8_t i;uint32_t e;uint16_t q;if(!h->transition_active)return;e=h->transition_elapsed+frames;if(e>=h->transition_total){for(i=0;i<HYBRID_CHANNELS;i++)h->engine[i].config=h->transition_to[i];h->transition_active=0;h->transition_elapsed=h->transition_total;return;}q=ratio_q15(e,h->transition_total);for(i=0;i<HYBRID_CHANNELS;i++){hybrid_channel_config_t*c=&h->engine[i].config;const hybrid_channel_config_t*a=&h->transition_from[i],*b=&h->transition_to[i];int32_t dv=(int32_t)b->volume-a->volume,dp=(int32_t)b->pan-a->pan;c->volume=(uint16_t)((int32_t)a->volume+(dv*(int32_t)q)/32767);c->pan=(int16_t)((int32_t)a->pan+(dp*(int32_t)q)/32767);}h->transition_elapsed=e;}
int hybrid_process(hybrid_core_t*h,int32_t*out,uint16_t frames){uint8_t i,solo;uint16_t f;if(!h||!out||!frames||frames>HYBRID_MAX_FRAMES)return -1;hybrid_zero(out,(uint32_t)frames*2u*(uint32_t)sizeof(int32_t));if(!h->initialized||h->master_mute)return 0;advance_transition(h,frames);solo=any_solo(h);for(i=0;i<HYBRID_CHANNELS;i++){hybrid_engine_slot_t*s=&h->engine[i];hybrid_channel_config_t*c=&s->config;int32_t lg,rg;const int32_t*source;if(!s->ops||!c->enabled||c->mute||(solo&&!c->solo)){s->pcm_valid=0;continue;}if(s->pcm_valid){if(s->pcm_frames!=frames){s->pcm_valid=0;return -2;}source=s->pcm_input;s->pcm_valid=0;s->pcm_frames=0;}else{if(!s->ops->render)continue;hybrid_zero(s->scratch,(uint32_t)frames*2u*(uint32_t)sizeof(int32_t));s->ops->render(s->state,s->scratch,frames);source=s->scratch;}lg=((int32_t)c->volume*(c->pan>0?100-c->pan:100))/100;rg=((int32_t)c->volume*(c->pan<0?100+c->pan:100))/100;for(f=0;f<frames;f++){out[2u*f]+=(source[2u*f]*lg)/Q15_ONE;out[2u*f+1u]+=(source[2u*f+1u]*rg)/Q15_ONE;}}for(f=0;f<frames*2u;f++)out[f]=clamp_q15(out[f]);return 0;}
int hybrid_scene_capture(hybrid_core_t*h,uint8_t n){uint8_t i;hybrid_scene_t*sc;if(!h||n>=HYBRID_SCENES)return -1;sc=&h->scenes[n];hybrid_zero(sc,(uint32_t)sizeof(*sc));for(i=0;i<HYBRID_CHANNELS;i++){hybrid_engine_slot_t*s=&h->engine[i];sc->channel[i]=s->config;if(s->ops&&s->ops->save_scene){int z=s->ops->save_scene(s->state,sc->engine_state[i],HYBRID_ENGINE_STATE);if(z<0||z>(int)HYBRID_ENGINE_STATE)return -1;sc->engine_state_size[i]=(uint8_t)z;}}sc->checksum=0x48594252u^n;h->scene_valid[n]=1;return 0;}
int hybrid_scene_recall(hybrid_core_t*h,uint8_t n,uint16_t ms){uint8_t i;uint32_t samples;hybrid_scene_t*sc;if(!h||n>=HYBRID_SCENES||!h->scene_valid[n])return -1;sc=&h->scenes[n];for(i=0;i<HYBRID_CHANNELS;i++){hybrid_engine_slot_t*s=&h->engine[i];if(s->ops&&s->ops->load_scene&&sc->engine_state_size[i]&&s->ops->load_scene(s->state,sc->engine_state[i],sc->engine_state_size[i])!=0)return -1;h->transition_from[i]=s->config;h->transition_to[i]=sc->channel[i];}samples=((uint32_t)ms*HYBRID_SAMPLE_RATE)/1000u;if(!samples){for(i=0;i<HYBRID_CHANNELS;i++)h->engine[i].config=sc->channel[i];h->transition_active=0;}else{h->transition_total=samples;h->transition_elapsed=0;h->transition_active=1;}h->selected_engine=HYBRID_AMB;return 0;}
void hybrid_scene_clear(hybrid_core_t*h,uint8_t n){if(!h||n>=HYBRID_SCENES)return;hybrid_zero(&h->scenes[n],(uint32_t)sizeof(h->scenes[n]));h->scene_valid[n]=0;}
void hybrid_panic(hybrid_core_t*h){uint8_t i;if(!h)return;for(i=0;i<HYBRID_CHANNELS;i++){hybrid_engine_slot_t*s=&h->engine[i];if(s->ops&&s->ops->panic)s->ops->panic(s->state);s->pcm_valid=0;s->pcm_frames=0;}}
